import {validateWearables} from './wearable-schema.js';
import {validateObjects,validateTailoring} from './studio-schema.js';
import {validateCreation} from './creation-schema.js';
export const designColors={original:null,cream:'#eee2ca',sage:'#9eae91',forest:'#526e5c',rose:'#bd9091',clay:'#b8896d',ocean:'#6d96a3',lavender:'#aba2be',walnut:'#8a705c'};
export const designFields={outfit:{garment:['original','plain','mint','amber','cream','navy','rose','sage','denim'],hat:['none','beret','beanie'],shoes:['none','sneakers','boots'],accessory:['none','bow','brooch'],primary:Object.keys(designColors),trim:Object.keys(designColors),motif:['none','flower','star','heart']},planet:{grass:['original','sage','forest'],water:['original','ocean','sage'],roof:Object.keys(designColors)},home:{layout:['original','garden','study'],wall:Object.keys(designColors),curtain:Object.keys(designColors),fabric:Object.keys(designColors),light:['original','warm','soft'],brightness:['normal','dim','bright']}};
export const defaultDesign=()=>({outfit:{garment:'original',hat:'none',shoes:'none',accessory:'none',primary:'original',trim:'original',motif:'none'},planet:{grass:'original',water:'original',roof:'original'},home:{layout:'original',wall:'original',curtain:'original',fabric:'original',light:'original',brightness:'normal'}});
export function validateDesignPart(scope,value){let objects,tailoring,headwear,accessoryColors,wearables;if(scope==='outfit'&&value&&Object.hasOwn(value,'headwear')){headwear=validateTailoring(value.headwear);if(headwear&&!['hat','veil'].includes(headwear.kind))throw Error('头饰类型不正确');value={...value};delete value.headwear;}if(scope==='outfit'&&value&&Object.hasOwn(value,'wearables')){wearables=validateWearables(value.wearables);value={...value};delete value.wearables;}if(scope==='outfit'&&value&&Object.hasOwn(value,'accessoryColors')){accessoryColors=value.accessoryColors;if(!accessoryColors||typeof accessoryColors!=='object'||Array.isArray(accessoryColors)||Object.entries(accessoryColors).some(([k,v])=>!['hat','shoes','accessory'].includes(k)||!/^#[a-fA-F0-9]{6}$/.test(v)))throw Error('配饰颜色不正确');value={...value};delete value.accessoryColors;}if(scope==='home'&&value&&Object.hasOwn(value,'objects')){objects=validateObjects(value.objects);value={...value};delete value.objects}if(scope==='outfit'&&value&&Object.hasOwn(value,'tailoring')){tailoring=validateTailoring(value.tailoring);value={...value};delete value.tailoring}let creation; if(value&&Object.hasOwn(value,'creation')){creation=validateCreation(scope,value.creation);value={...value};delete value.creation}const fields=designFields[scope];if(!fields||!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length!==Object.keys(fields).length||Object.keys(value).some(k=>!Object.hasOwn(fields,k)))throw new Error('设计包含未开放的修改');for(const [k,allowed]of Object.entries(fields))if(!allowed.includes(value[k]))throw new Error('设计参数超出范围');return {...Object.fromEntries(Object.keys(fields).map(k=>[k,value[k]])),...(creation!==undefined?{creation}:{}),...(objects!==undefined?{objects}:{}),...(tailoring!==undefined?{tailoring}:{}),...(headwear!==undefined?{headwear}:{}),...(accessoryColors!==undefined?{accessoryColors}: {}),...(wearables!==undefined?{wearables}:{})}}
export function validateDesign(value){if(!value||Object.keys(value).length!==3)throw new Error('设计数据不完整');return Object.fromEntries(Object.keys(designFields).map(scope=>[scope,validateDesignPart(scope,{...(scope==='outfit'?{garment:'original',hat:'none',shoes:'none',accessory:'none'}:scope==='home'?{layout:'original'}:{}),...value[scope]})]))}
export const designExamples={outfit:{garment:'cream',hat:'beret',shoes:'sneakers',accessory:'brooch',primary:'cream',trim:'forest',motif:'flower'},planet:{grass:'sage',water:'ocean',roof:'clay'},home:{layout:'original',wall:'cream',curtain:'sage',fabric:'rose',light:'warm',brightness:'normal'}};
